<#
.SYNOPSIS
  Builds the role-by-role review matrix (Required information | Actually visible | Actually returned by API | Unnecessary information/actions |
  Server-side enforcement test | Result) from what group R of run_e2e.ps1 MEASURED: role_ui_inventory.json (what each role's page showed and requested),
  role_api_inventory.json (the response fields each role received) and scenario_matrix.json (the executed test rows of the SAME full run).
.DESCRIPTION
  "Required" is the specification written below. "Actually visible" and "Actually returned" are measured. "Unnecessary" is computed as
  measured minus required (plus explicit notes). "Result" is PASS only when every referenced test row passed in the matrix (an id ending in *
  means every row of that group); a role is called fully verified only when its UI rows AND its API rows passed.
  Updated for the 2026-10-12 interface redesign (navigation labels, dl labels, appointment management).
.EXAMPLE
  powershell -NoProfile -ExecutionPolicy Bypass -File tests\e2e\build_role_matrix.ps1 -RunDir <run folder>   (after a full run_e2e.ps1 run that included groups B, R and T)
#>
param([string]$RunDir, [string]$Out)
$ErrorActionPreference = 'Stop'
if (-not $RunDir) { $RunDir = (Get-Content (Join-Path $env:LOCALAPPDATA 'zt-demo\current.txt') -TotalCount 1).Trim() }
$rep = Join-Path $RunDir 'reports'
$ui = ConvertFrom-Json -InputObject (Get-Content (Join-Path $rep 'role_ui_inventory.json') -Raw)
$api = ConvertFrom-Json -InputObject (Get-Content (Join-Path $rep 'role_api_inventory.json') -Raw)
$rows = ConvertFrom-Json -InputObject (Get-Content (Join-Path $rep 'scenario_matrix.json') -Raw)
if (-not $Out) { $Out = Join-Path $rep 'role_matrix.md' }
$res = @{}; foreach ($r in $rows) { $res[[string]$r.Id] = [string]$r.Result }
$groupsRun = @($rows | ForEach-Object { [string]$_.Group } | Sort-Object -Unique)
if ($groupsRun -notcontains 'R' -or $groupsRun -notcontains 'B') { throw "scenario_matrix.json must come from one full run that included groups B and R (found: $($groupsRun -join ','))" }

function Keys($role, $surface) { $s = $api.$role.PSObject.Properties[$surface]; if ($s) { @($s.Value.keys) } else { @() } }
function Stat($role, $surface) { $s = $api.$role.PSObject.Properties[$surface]; if ($s) { "{0}{1}" -f $s.Value.status, $(if ($s.Value.code) { ' ' + $s.Value.code } else { '' }) } else { 'not probed' } }
function Ids($role) { $s = $api.$role.PSObject.Properties['list']; if ($s -and $s.Value.ids) { [string]$s.Value.ids } else { '-' } }
function UiTab($role, $tab, $field) { $t = $ui.roles.$role.tabs.PSObject.Properties[$tab]; if ($t) { @($t.Value.$field) } else { @() } }
function UiDet($role, $prefix, $field) { @($ui.roles.$role.details.PSObject.Properties | Where-Object { $_.Name -like "$prefix*" } | ForEach-Object { @($_.Value.$field) }) }
function U($a) { @($a | Where-Object { $_ } | Select-Object -Unique) }
function J($a, [string]$none = '-') { $x = @(U $a); if ($x.Count -eq 0) { $none } else { $x -join ', ' } }
function Surplus([string[]]$actual, [string[]]$allowed) { @($actual | Where-Object { $allowed -notcontains $_ }) }
function Expand([string[]]$ids) { foreach ($i in $ids) { if ($i.EndsWith('*')) { $p = $i.TrimEnd('*'); $res.Keys | Where-Object { $_ -match ('^' + [regex]::Escape($p) + '\d') } } else { $i } } }
function Verdict([string[]]$ids) {
    $all = @(Expand $ids)
    $bad = @($all | Where-Object { $res[$_] -ne 'PASS' })
    if ($bad.Count -eq 0) { 'PASS' } else { 'FAIL: ' + (($bad | ForEach-Object { "$_ ($($res[$_]))" }) -join ', ') }
}
$LIST = 'patients[].patient_id', 'patients[].name', 'patients[].dob', 'patients[].ward', 'patients[].next_appointment', 'patients[].access_basis'
$SUMM = 'patient_id', 'name', 'dob', 'ward', 'next_appointment', 'access_basis'
$md = New-Object System.Collections.Generic.List[string]
$allVerdicts = @{}
function Row([string]$role, [string]$area, [string]$required, [string]$visible, [string]$returned, [string]$unnecessary, [string]$tests, [string[]]$ids) {
    $v = Verdict $ids
    $script:md.Add(('| {0} | {1} | {2} | {3} | {4} | {5} | {6} |' -f $area, ($required -replace '\|', '/'), ($visible -replace '\|', '/'), ($returned -replace '\|', '/'), ($unnecessary -replace '\|', '/'), ($tests -replace '\|', '/'), $v))
    if (-not $script:allVerdicts.ContainsKey($role)) { $script:allVerdicts[$role] = @() }
    $script:allVerdicts[$role] += $v
}
function Head([string]$title) { $md.Add(''); $md.Add("### $title"); $md.Add(''); $md.Add('| Area | Required information | Actually visible (page, measured) | Actually returned by API (fields, measured) | Unnecessary information / actions | Server-side enforcement test | Result |'); $md.Add('|---|---|---|---|---|---|---|') }
function SessionKeys($role) { $k = Keys $role 'session'; ('{0} fields: user.*, session.*, device.* (id, kind, label, posture, score, signals), network.*, policy groups [{1}], token_ttl_seconds, simulation_enabled' -f $k.Count, (J (@($k | Where-Object { $_ -like 'policy.*' } | ForEach-Object { ($_ -split '\.')[1] }))) ) }
function DemoVisible($role) { ('Demonstration tools (evaluation aid): buttons {0}; inputs {1}' -f (J (UiTab $role 'Demonstration tools' 'buttons')), (J (UiTab $role 'Demonstration tools' 'inputs'))) }
function FirstBanner($role, $prefix) { $b = @(UiDet $role $prefix 'banner' | Where-Object { $_ }); if ($b.Count) { [string]$b[0] } else { '-' } }
$SESSIONTHRESH = 'policy fields beyond the user''s thresholds: '

$md.Add('# Role-by-role review matrix (measured)')
$md.Add('')
$md.Add("Run folder: $RunDir. Generated from role_ui_inventory.json (real Chrome, real clicks), role_api_inventory.json (the same calls made directly against the PEP) and scenario_matrix.json (executed test rows of one full run: groups $($groupsRun -join ', ')). A role is called fully verified only when its UI rows and its API rows all passed.")

# ------------------------------------------------------------------ DOCTOR
Head 'Doctor (dr_alice)'
$items = @(UiTab 'dr_alice' 'My patients' 'listItems')
Row 'doctor' 'Patient list' 'Only the patients assigned to the doctor: id, name, date of birth, ward, next appointment, access basis' ("{0} patients listed ({1}); badges: {2}; an ID box (needed to reach a patient for emergency access)" -f $items.Count, (($items | ForEach-Object { ($_ -split ' ID ')[0] }) -join ', '), (J (UiTab 'dr_alice' 'My patients' 'badges'))) ("{0}; ids {1}; fields: {2}" -f (Stat 'doctor' 'list'), (Ids 'doctor'), (J (Keys 'doctor' 'list'))) ("fields beyond the required set: " + (J (Surplus (Keys 'doctor' 'list') $LIST) 'none')) 'R1, R16, AP3, W5' @('R1', 'R16', 'AP3', 'W5')
Row 'doctor' 'Patient banner (summary)' 'Name, id, date of birth, ward and next appointment of an assigned patient' ("banner: {0}" -f (FirstBanner 'dr_alice' 'listed')) ("assigned: {0}; unassigned: {1}; fields: {2}" -f (Stat 'doctor' 'summary_101'), (Stat 'doctor' 'summary_103'), (J (Keys 'doctor' 'summary_101'))) ("fields beyond the required set: " + (J (Surplus (Keys 'doctor' 'summary_101') $SUMM) 'none')) 'R2, R16, AP3' @('R2', 'R16', 'AP3')
Row 'doctor' 'Clinical record' 'Diagnosis, medication, care notes of an assigned patient (nothing already shown in the summary)' ("sections: {0}" -f (J (UiDet 'dr_alice' 'listed' 'headings' | Where-Object { $_ -in 'Diagnosis', 'Medication', 'Care notes' }))) ("assigned: {0}; unassigned: {1}; fields: {2}" -f (Stat 'doctor' 'records_101'), (Stat 'doctor' 'records_103'), (J (Keys 'doctor' 'records_101'))) ("repeated name/date of birth/ward removed in the role review; fields beyond required: " + (J (Surplus (Keys 'doctor' 'records_101') @('patient_id', 'access_basis', 'diagnosis', 'medication', 'care_notes')) 'none')) 'R3, AP3, UI3' @('R3', 'AP3', 'UI3')
Row 'doctor' 'Export (SSN and billing)' 'Not needed for treatment; kept as the single high-sensitivity action: assigned patients only, step-up PIN, never under emergency access; identifiers masked on screen by default' ("button: {0}" -f (J (UiDet 'dr_alice' 'listed' 'buttons' | Where-Object { $_ -like 'Export*' }))) ("assigned: {0}; unassigned: {1}; fields: {2}" -f (Stat 'doctor' 'export_101'), (Stat 'doctor' 'export_103'), (J (Keys 'doctor' 'export_101'))) 'NOTE: SSN and billing (synthetic) are returned by design as the demonstration of the top sensitivity tier; remove the endpoint for any real use' 'R4, BG2, AP3, AP7' @('R4', 'BG2', 'AP3', 'AP7')
Row 'doctor' 'Unassigned patient and emergency access' 'Refusal with a plain-language reason; emergency option with a justification and a confirmation; read-only, one patient, this sign-in only, approved duration with a visible countdown, no export' ("alerts: {0}; button: {1}; dialog: {2}" -f (J (UiDet 'dr_alice' 'unlisted' 'banners')), (J (UiDet 'dr_alice' 'unlisted' 'buttons' | Where-Object { $_ -like '*emergency*' })), (J ($ui.roles.dr_alice.modals.PSObject.Properties | ForEach-Object { $_.Value.inputs + $_.Value.buttons }))) ("denial {0}, fields: {1}; grant response: {2}" -f (Stat 'doctor' 'records_103'), (J (Keys 'doctor' 'records_103')), (J (Keys 'doctor' 'breakglass_granted'))) 'NOTE: while the evaluation tools are enabled (the default in this academic build) the denial body still carries the risk score, session risk and scoring breakdown and the page ignores them (it shows a plain-language reason only, no technical detail); a missing patient number is answered like an unassigned one (X4, X6); with the tools off the server withholds the figures (X9)' 'BG1-BG6, AP7, R2, R17, E*, U5, RU4, X4, X6' @('BG1', 'BG2', 'BG3', 'BG4', 'BG5', 'BG6', 'AP7', 'R2', 'R17', 'E*', 'U5', 'RU4', 'X4', 'X6')
Row 'doctor' 'Account and session feedback' 'Name, role, sign-in time, the automatic sign-out and the longest session (compact account menu); a plain notice shortly before the session ends; a plain end-of-session screen. No risk, device or network information anywhere in the workspace' ("top bar: {0}; navigation: {1}" -f (J $ui.roles.dr_alice.header), (J ($ui.roles.dr_alice.tabs.PSObject.Properties.Name))) (SessionKeys 'doctor') ('NOTE: while the administrator has the evaluation tools enabled (the default in this academic build) /ctl/session still returns the session''s risk points, device posture and network addresses to this role and the page ignores them; with the tools off the server returns only identity, the session limits and the emergency-access rules (X9, X10). Policy fields beyond the user''s thresholds: ' + (J @(Keys 'doctor' 'session' | Where-Object { $_ -match '^policy\.(penalties|device|behavior|login|network|admin|break_glass)\.' }) 'none')) 'RU1, RU12, RU13, RU14, X9, X10, R11, UI5' @('RU1', 'RU12', 'RU13', 'RU14', 'X9', 'X10', 'R11', 'UI5')
Row 'doctor' 'Evaluation mode (off by default)' 'Nothing for the job: an opt-in aid for the demonstration (page address with ?evaluation=1 and the administrator''s evaluation switch): the user''s own session, device and network evidence, direct API probes, 5 restricted requests, SIMULATED network and posture switches' ("normal navigation: {0}; evaluation mode adds My session and Demonstration tools (RU11)" -f (J ($ui.roles.dr_alice.tabs.PSObject.Properties.Name))) 'the probes call /api/patients/{id}/summary|records|export-pdf and /ctl/simulate; see R14, R15 for the tampering variants and U1-U3 for the screens' 'NOTE: invisible in the normal workspace; with the switch off the server refuses /ctl/simulate and withholds the figures (X9-X11); it adds no access the role does not already have' 'RU11, X9, X10, X11, R14, R15, B*, C*, D*, U1, U2, U3' @('RU11', 'X9', 'X10', 'X11', 'R14', 'R15', 'B*', 'C*', 'D*', 'U1', 'U2', 'U3')
Row 'doctor' 'Administration and other roles' 'None' ("navigation: {0}" -f (J ($ui.roles.dr_alice.tabs.PSObject.Properties.Name))) ("11 administration calls: {0}" -f (J (@('admin_summary', 'admin_policy_set', 'admin_unlock') | ForEach-Object { Stat 'doctor' $_ }))) ("none (/ctl/policy now refused: {0}; appointment changes refused: see T2)" -f (Stat 'doctor' 'policy')) 'R10, R11, R18, T2' @('R10', 'R11', 'R18', 'T2')
Row 'doctor' 'Database access' 'List: patients joined to the doctor''s assignments, directory columns only. Record: diagnosis, medication, care notes. Export: identity, diagnosis, medication, encrypted SSN/billing. Grants and assignments for the check' 'n/a (no screen)' 'n/a (server internal; verified in code, see tests)' 'only the columns of the request kind are selected (minimised in the role review)' 'R19, AP3, AP7' @('R19', 'AP3', 'AP7')

# ------------------------------------------------------------------ NURSE
Head 'Nurse (nurse_bob, ward A)'
$items = @(UiTab 'nurse_bob' 'Ward patients' 'listItems')
Row 'nurse' 'Ward patient list' 'Patients of the nurse''s ward: id, name, date of birth, ward, next appointment' ("{0} patients listed ({1}); badges: {2}" -f $items.Count, (($items | ForEach-Object { ($_ -split ' ID ')[0] }) -join ', '), (J (UiTab 'nurse_bob' 'Ward patients' 'badges'))) ("{0}; ids {1}; fields: {2}" -f (Stat 'nurse' 'list'), (Ids 'nurse'), (J (Keys 'nurse' 'list'))) ("fields beyond the required set: " + (J (Surplus (Keys 'nurse' 'list') $LIST) 'none')) 'R5, R16, AP2' @('R5', 'R16', 'AP2')
Row 'nurse' 'Care record' 'Medication and care notes of ward patients; NO diagnosis' ("sections: {0}" -f (J (UiDet 'nurse_bob' 'listed' 'headings' | Where-Object { $_ -in 'Diagnosis', 'Medication', 'Care notes' }))) ("ward patient: {0}; fields: {1}" -f (Stat 'nurse' 'records_101'), (J (Keys 'nurse' 'records_101'))) ("fields beyond required: " + (J (Surplus (Keys 'nurse' 'records_101') @('patient_id', 'access_basis', 'medication', 'care_notes')) 'none') + '; diagnosis present: ' + [bool]((Keys 'nurse' 'records_101') -contains 'diagnosis')) 'R6, AP2, UI2' @('R6', 'AP2', 'UI2')
Row 'nurse' 'Other wards' 'Refusal with the reason (patient is on another ward)' ("alerts: {0}" -f (J (UiDet 'nurse_bob' 'unlisted' 'banners'))) ("summary 102: {0}; records 102: {1}; summary 104: {2}" -f (Stat 'nurse' 'summary_102'), (Stat 'nurse' 'records_102'), (Stat 'nurse' 'summary_104')) 'NOTE: while the evaluation tools are enabled the denial body carries risk figures and the page ignores them; the screen shows a plain-language reason; a missing patient number is answered like a patient of another ward (X5)' 'R6, R16, R17, AP2, X5' @('R6', 'R16', 'R17', 'AP2', 'X5')
Row 'nurse' 'Export and emergency access' 'Not available to nurses' ("buttons in patient views: {0}" -f (J (UiDet 'nurse_bob' 'listed' 'buttons') 'none')) ("export: {0}; break-glass: {1}" -f (Stat 'nurse' 'export_101'), (Stat 'nurse' 'breakglass_104')) 'none' 'R6, AP2, UI2, R18' @('R6', 'AP2', 'UI2', 'R18')
Row 'nurse' 'Account and session feedback' 'Name, role, sign-in time, the automatic sign-out and the longest session (compact account menu); a plain notice shortly before the session ends; a plain end-of-session screen. No risk, device or network information anywhere in the workspace' ("top bar: {0}; navigation: {1}" -f (J $ui.roles.nurse_bob.header), (J ($ui.roles.nurse_bob.tabs.PSObject.Properties.Name))) (SessionKeys 'nurse') ('NOTE: while the administrator has the evaluation tools enabled (the default in this academic build) /ctl/session still returns the session''s risk points, device posture and network addresses to this role and the page ignores them; with the tools off the server returns only identity and the session limits (X9, X10). Policy fields beyond the user''s thresholds: ' + (J @(Keys 'nurse' 'session' | Where-Object { $_ -match '^policy\.(penalties|device|behavior|login|network|admin|break_glass)\.' }) 'none')) 'RU2, RU12, RU13, RU14, X9, X10, R11, UI5' @('RU2', 'RU12', 'RU13', 'RU14', 'X9', 'X10', 'R11', 'UI5')
Row 'nurse' 'Evaluation mode (off by default)' 'Nothing for the job: an opt-in aid for the demonstration (page address with ?evaluation=1 and the administrator''s evaluation switch): the user''s own session, device and network evidence, direct API probes, 5 restricted requests, SIMULATED network and posture switches' ("normal navigation: {0}; evaluation mode adds My session and Demonstration tools (RU11)" -f (J ($ui.roles.nurse_bob.tabs.PSObject.Properties.Name))) 'the probes call /api/patients/{id}/summary|records|export-pdf and /ctl/simulate; see R14, R15 for the tampering variants and U1-U3 for the screens' 'NOTE: invisible in the normal workspace; with the switch off the server refuses /ctl/simulate and withholds the figures (X9-X11); it adds no access the role does not already have; the "Export" probe is not offered to nurses' 'RU11, X9, X10, X11, R14, R15, B*, C*, D*' @('RU11', 'X9', 'X10', 'X11', 'R14', 'R15', 'B*', 'C*', 'D*')
Row 'nurse' 'Administration' 'None' ("navigation: {0}" -f (J ($ui.roles.nurse_bob.tabs.PSObject.Properties.Name))) ("admin calls: {0}" -f (J (@('admin_summary', 'admin_policy_set', 'admin_unlock') | ForEach-Object { Stat 'nurse' $_ }))) 'none (appointment changes refused: see T2)' 'R10, R18, T2' @('R10', 'R18', 'T2')
Row 'nurse' 'Database access' 'List: patients of the ward or assigned to the nurse, directory columns only. Care record: medication and care notes (the diagnosis column is never selected for a nurse). No export' 'n/a (no screen)' 'n/a (server internal; verified in code, see tests)' 'the diagnosis column is not read for a nurse at all' 'R19, AP2' @('R19', 'AP2')

# ------------------------------------------------------------------ RECEPTIONIST
Head 'Receptionist (front_carol)'
$items = @(UiTab 'front_carol' 'Patient registry' 'listItems')
Row 'receptionist' 'Patient registry' 'All patients, front-desk data only: id, name, date of birth, ward, next appointment' ("{0} patients listed; badges: {1}" -f $items.Count, (J (UiTab 'front_carol' 'Patient registry' 'badges'))) ("{0}; ids {1}; fields: {2}" -f (Stat 'receptionist' 'list'), (Ids 'receptionist'), (J (Keys 'receptionist' 'list'))) ("fields beyond the required set: " + (J (Surplus (Keys 'receptionist' 'list') $LIST) 'none') + '; NOTE: access_basis is constant "front_desk" (uniform response shape)') 'R7, AP1' @('R7', 'AP1')
Row 'receptionist' 'Patient demographics' 'Demographics and next appointment' ("labels: {0}" -f (J (UiDet 'front_carol' 'listed' 'kvLabels'))) ("{0}; fields: {1}" -f (Stat 'receptionist' 'summary_101'), (J (Keys 'receptionist' 'summary_101'))) ("fields beyond required: " + (J (Surplus (Keys 'receptionist' 'summary_101') $SUMM) 'none')) 'R7, AP1, UI1' @('R7', 'AP1', 'UI1')
Row 'receptionist' 'Appointment management' 'Move the next appointment of a patient (date and time); nothing else is written' ("Appointments screen: columns {0}; buttons {1}; dialog: {2}" -f (J (UiTab 'front_carol' 'Appointments' 'tableHeaders')), (J ((UiTab 'front_carol' 'Appointments' 'buttons') | Select-Object -First 2)), (J ($ui.roles.front_carol.modals.PSObject.Properties | ForEach-Object { $_.Value.inputs + $_.Value.buttons }))) 'POST /api/patients/{id}/appointment {next_appointment}: answer fields message, next_appointment, patient_id (see T1)' 'none: validated by the server (real future date within 12 months, 2 KB body), refused for every other role at the policy engine and again in the protected app' 'T1-T9, AP8-AP10, U6, R18' @('T*', 'AP8', 'AP9', 'AP10', 'U6', 'R18')
Row 'receptionist' 'Clinical details (diagnosis, notes, medication, export, emergency access)' 'Nothing: no clinical section, field, button, navigation item or value' ("clinical headings: {0}; buttons in patient views: {1}" -f (J (UiDet 'front_carol' 'listed' 'headings' | Where-Object { $_ -match 'Clinical|Diagnosis|Medication' }) 'none'), (J (UiDet 'front_carol' 'listed' 'buttons') 'none')) ("records: {0}; export: {1}; break-glass: {2}; clinical values in any response it received: see R7" -f (Stat 'receptionist' 'records_101'), (Stat 'receptionist' 'export_101'), (Stat 'receptionist' 'breakglass_104')) 'none (the tools screen has one neutral "access-control test" button; the refusal is shown by the server)' 'R7, R14, R15, AP1, UI1, T6' @('R7', 'R14', 'R15', 'AP1', 'UI1', 'T6')
Row 'receptionist' 'Account and session feedback' 'Name, role, sign-in time, the automatic sign-out and the longest session (compact account menu); a plain notice shortly before the session ends; a plain end-of-session screen. No risk, device or network information anywhere in the workspace' ("top bar: {0}; navigation: {1}" -f (J $ui.roles.front_carol.header), (J ($ui.roles.front_carol.tabs.PSObject.Properties.Name))) (SessionKeys 'receptionist') ('NOTE: while the administrator has the evaluation tools enabled (the default in this academic build) /ctl/session still returns the session''s risk points, device posture and network addresses to this role and the page ignores them; with the tools off the server returns only identity and the session limits (X9, X10). Policy fields beyond the user''s thresholds: ' + (J @(Keys 'receptionist' 'session' | Where-Object { $_ -match '^policy\.(penalties|device|behavior|login|network|admin|break_glass)\.' }) 'none')) 'RU3, RU12, RU13, RU14, X9, X10, R11, UI5' @('RU3', 'RU12', 'RU13', 'RU14', 'X9', 'X10', 'R11', 'UI5')
Row 'receptionist' 'Evaluation mode (off by default)' 'Nothing for the job: an opt-in aid for the demonstration (page address with ?evaluation=1 and the administrator''s evaluation switch): the user''s own session, device and network evidence, direct API probes, 5 restricted requests, SIMULATED network and posture switches' ("normal navigation: {0}; evaluation mode adds My session and Demonstration tools (RU11)" -f (J ($ui.roles.front_carol.tabs.PSObject.Properties.Name))) 'the probes call /api/patients/{id}/summary|records|export-pdf and /ctl/simulate; see R14, R15 for the tampering variants and U1-U3 for the screens' 'NOTE: invisible in the normal workspace; with the switch off the server refuses /ctl/simulate and withholds the figures (X9-X11); it adds no access the role does not already have; no clinical wording or clinical action button is shown to this role' 'RU11, X9, X10, X11, R14, R15, B*, C*, D*, UI1' @('RU11', 'X9', 'X10', 'X11', 'R14', 'R15', 'B*', 'C*', 'D*', 'UI1')
Row 'receptionist' 'Administration' 'None' ("navigation: {0}" -f (J ($ui.roles.front_carol.tabs.PSObject.Properties.Name))) ("admin calls: {0}" -f (J (@('admin_summary', 'admin_policy_set', 'admin_unlock') | ForEach-Object { Stat 'receptionist' $_ }))) 'none' 'R10, R18' @('R10', 'R18')
Row 'receptionist' 'Database access' 'List: directory columns of all patients. Summary: name, date of birth, ward, next appointment. Appointment change: the next_appointment column only. Nothing else' 'n/a (no screen)' 'n/a (server internal; verified in code, see tests)' 'diagnosis, medication, care notes and the encrypted SSN/billing columns are never selected for this role' 'R19, AP1, AP10' @('R19', 'AP1', 'AP10')

# ------------------------------------------------------------------ SECURITY ADMINISTRATOR
Head 'Security administrator (sec_dan)'
Row 'security_admin' 'Overview (counters, risk alerts)' 'Active/revoked sessions, denials, step-ups, revocations, locked accounts, emergency access, devices; risk alerts; latest events' ("stats: {0}; panels: {1}" -f (J (UiTab 'sec_dan' 'Overview' 'stats')), (J (UiTab 'sec_dan' 'Overview' 'headings'))) ("summary {0}: {1}; sessions {2}: {3}" -f (Stat 'security_admin' 'admin_summary'), (J (Keys 'security_admin' 'admin_summary')), (Stat 'security_admin' 'admin_sessions'), (J (Keys 'security_admin' 'admin_sessions'))) 'none (user_id is returned next to the username; harmless for the administrator)' 'R9, UI4, F*' @('R9', 'UI4', 'F*')
Row 'security_admin' 'Sessions' 'Per session: user, role, device (fingerprint, no computer name), network, risk level, status, revocation reason; revoke' ("columns: {0}; buttons: {1}" -f (J (UiTab 'sec_dan' 'Sessions' 'tableHeaders')), (J ((UiTab 'sec_dan' 'Sessions' 'buttons') | Select-Object -First 5))) ("{0}: {1}" -f (Stat 'security_admin' 'admin_sessions'), (J (Keys 'security_admin' 'admin_sessions'))) 'none' 'R9, UI4, UI7, U4' @('R9', 'UI4', 'UI7', 'U4')
Row 'security_admin' 'Access decisions and audit log' 'Every decision with who, what request, decision, reason, effect on risk; every other security event with filters' ("columns: {0}" -f (J ((UiTab 'sec_dan' 'Audit log' 'tableHeaders') | Select-Object -First 7))) ("{0}: {1}" -f (Stat 'security_admin' 'admin_events'), (J (Keys 'security_admin' 'admin_events'))) 'patient ids appear in request paths (needed for audit); no patient name or clinical value (R9); raw device identifiers in audit text are replaced by fingerprints on screen (UI7); break-glass justifications are free text written by doctors: the emergency dialog warns them not to write clinical details' 'R9, F*, UI7' @('R9', 'F*', 'UI7')
Row 'security_admin' 'Devices and posture' 'Device kind, posture, signals with provenance (measured / self-reported / simulated), agent demonstration mode' ("{0} device panels (this run also holds devices of earlier tests); labels: {1}" -f @(UiTab 'sec_dan' 'Devices & posture' 'headings').Count, (J (UiTab 'sec_dan' 'Devices & posture' 'kvLabels'))) ("{0}: {1}" -f (Stat 'security_admin' 'admin_devices'), (J (Keys 'security_admin' 'admin_devices'))) 'none (the host name field is returned by the API but never shown)' 'R9, F*, C*, UI7' @('R9', 'F*', 'C*', 'UI7')
Row 'security_admin' 'Policy' 'Full editable policy with plain-language labels; every change audited' ("sections: {0}; {1} Apply buttons" -f (J (UiTab 'sec_dan' 'Policy' 'headings')), @(UiTab 'sec_dan' 'Policy' 'buttons' | Where-Object { $_ -eq 'Apply' }).Count) ("{0}: {1} fields" -f (Stat 'security_admin' 'admin_policy'), @(Keys 'security_admin' 'admin_policy').Count) 'none (the policy is shown once; My session does not repeat it)' 'R11, UI4, D*' @('R11', 'UI4', 'D*')
Row 'security_admin' 'Users and emergency access' 'Accounts with lock state and unlock; emergency grants with justification (plain text), status, revoke' ("account/grant columns: {0}" -f (J (UiTab 'sec_dan' 'Users & access' 'tableHeaders'))) ("grants {0}: {1}; users {2}: {3}" -f (Stat 'security_admin' 'admin_grants'), (J (Keys 'security_admin' 'admin_grants')), (Stat 'security_admin' 'admin_users'), (J (Keys 'security_admin' 'admin_users'))) 'none: no password or PIN hash, no encrypted identifier in any administration response (R9)' 'R9, E*' @('R9', 'E*')
Row 'security_admin' 'Clinical access (default)' 'None: no patient list, summary, record, export, no emergency access, no appointment change; no mechanism exists in this build to grant the administrator clinical access' ("navigation: {0}; patient names or clinical values on any screen: see UI4" -f (J ($ui.roles.sec_dan.tabs.PSObject.Properties.Name))) ("list {0}; summary {1}; records {2}; export {3}; break-glass {4}" -f (Stat 'security_admin' 'list'), (Stat 'security_admin' 'summary_101'), (Stat 'security_admin' 'records_101'), (Stat 'security_admin' 'export_101'), (Stat 'security_admin' 'breakglass_104')) 'none' 'R8, R9, R14, R15, AP4, UI4, R18, T2' @('R8', 'R9', 'R14', 'R15', 'AP4', 'UI4', 'R18', 'T2')
Row 'security_admin' 'Own session' 'Own identity, risk level, device status' ("My session labels: {0}" -f (J (UiTab 'sec_dan' 'My session' 'kvLabels'))) (SessionKeys 'security_admin') 'NOTE: /ctl/session still returns the full policy to the administrator (also available through /admin/policy); redundant but harmless for this role, not changed' 'UI4' @('UI4')
Row 'security_admin' 'Database access' 'sessions, users (no hashes), devices, security events, break-glass grants, policy; never the patients table' 'n/a (no screen)' 'n/a (server internal; verified in code, see tests)' 'no clinical or encrypted column is named anywhere in the PDP sources' 'R19, R9, AP4' @('R19', 'R9', 'AP4')

# ------------------------------------------------------------------ frontend requests (what each page asked the server for)
$md.Add('')
$md.Add('### Requests each role''s page actually made (from the page inventory)')
$md.Add('')
$md.Add('| Role | Call | Times | Fields of the answer |')
$md.Add('|---|---|---|---|')
foreach ($u in $ui.roles.PSObject.Properties.Name) {
    foreach ($q in @($ui.roles.$u.requests)) {
        $k = @($q.keys); $kt = if ($k.Count -le 14) { $k -join ', ' } else { (($k | Select-Object -First 14) -join ', ') + (', ... ({0} fields)' -f $k.Count) }
        $md.Add(('| {0} | {1} | {2} | {3} |' -f $u, $q.call, $q.count, $kt))
    }
}

# ------------------------------------------------------------------ verdict per role
$md.Add('')
$md.Add('### Verdict per role')
$md.Add('')
$md.Add('| Role | UI and API both checked | Rows | Verdict |')
$md.Add('|---|---|---|---|')
foreach ($r in 'doctor', 'nurse', 'receptionist', 'security_admin') {
    $v = @($allVerdicts[$r]); $bad = @($v | Where-Object { $_ -ne 'PASS' })
    $md.Add(('| {0} | yes (page inventory in real Chrome + the same calls made directly) | {1} | {2} |' -f $r, $v.Count, $(if ($bad.Count -eq 0) { 'all rows PASS' } else { $bad.Count.ToString() + ' row(s) not PASS: ' + (($bad | Select-Object -First 3) -join ' / ') })))
}
[System.IO.File]::WriteAllLines($Out, [string[]]$md)
Write-Output "role matrix written: $Out ($($md.Count) lines)"
